import sys

def main():
    data = sys.stdin.read().strip().split()
    n = int(data[0])
    arr = list(map(int, data[1:1+n]))
    first = second = -10**18
    for x in arr:
        if x > first:
            second = first
            first = x
        elif x != first and x > second:
            second = x
    print(second)

if __name__ == "__main__":
    main()
